<div class="row g-3"><div class="col-lg-4"><div class="km-card p-3"><h4>Nouveau fournisseur</h4><form method="post" action="<?=e(base_url('suppliers'))?>"><?=csrf_field()?><label class="form-label">Entreprise *</label><input class="form-control" name="company_name" required><label class="form-label mt-2">Contact</label><input class="form-control" name="contact_name"><label class="form-label mt-2">Téléphone</label><input class="form-control" name="phone"><label class="form-label mt-2">E-mail</label><input class="form-control" name="email"><label class="form-label mt-2">Adresse</label><input class="form-control" name="address"><label class="form-label mt-2">Délai moyen (jours)</label><input class="form-control" type="number" name="lead_time_days" value="3"><input type="hidden" name="debt" value="0"><button class="btn btn-km mt-3">Ajouter</button></form></div></div><div class="col-lg-8"><div class="km-card p-3"><h4>Fournisseurs</h4><div class="table-responsive"><table class="table"><thead><tr><th>Entreprise</th><th>Contact</th><th>Délai</th><th>Total achats</th><th>Dette</th></tr></thead><tbody><?php foreach($suppliers as $s):?><tr><td><strong><?=e($s['company_name'])?></strong></td><td><?=e($s['contact_name'])?><div class="small text-muted"><?=e($s['phone'])?></div></td><td><?=e($s['lead_time_days'])?> j</td><td><?=money($s['total_purchases'])?></td><td><?=money($s['debt'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>